/**
 * Reads the cached cart count from session and synchronizes the header badge.
 */
export function verifyCartCount() {
  const cachedCount = session.getItem('ecmd_cached_cart_count') || '0';
  const numericCount = parseInt(cachedCount, 10) || 0;

  console.info(`📌 [MASTER_PAGE -> verifyCartCount]: Syncing live cart badge count=${numericCount}`);

  if ($w('#cartBadgeText')) {
    $w('#cartBadgeText').text = String(numericCount);
  }

  if ($w('#cartBadgeBox')) {
    if (numericCount > 0) {
      $w('#cartBadgeBox').show();
      $w('#cartBadgeBox').expand();
    } else {
      $w('#cartBadgeBox').hide();
      $w('#cartBadgeBox').collapse();
    }
  }

  return numericCount;
}

